WITH parsed AS (SELECT id, created_at, ship_to, EXISTS(items, i -> i.price > 100) AS has_premium_item, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, FORALL(items, i -> i.qty <= 5) AS all_small_qty, COALESCE(attributes['gift'], 'unknown') AS gift_or_default, ship_to.zip AS ship_zip FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, MIN(created_at) AS started_at, COUNT(*) AS event_count, COUNT(*) AS event_count_2, MAX(created_at) AS ended_at FROM parsed GROUP BY hour_window HAVING COUNT(DISTINCT id) < 1000
